create extension if not exists pgcrypto;
create table users(id uuid primary key default gen_random_uuid(),email text unique not null,password_hash text,name text not null,phone text,role text not null default 'MEMBER',status text not null default 'ACTIVE',created_at timestamptz not null default now());
create table campaigns(id uuid primary key default gen_random_uuid(),slug text unique not null,type text not null check(type in('CPA','POSTING')),title text not null,category text,reward integer not null default 0,status text not null default 'DRAFT',summary text,approval_condition text,duplicate_days integer,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table campaign_participants(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns(id),user_id uuid not null references users(id),tracking_code text unique,status text not null default 'ACTIVE',created_at timestamptz not null default now(),unique(campaign_id,user_id));
create table clicks(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns(id),participant_id uuid references campaign_participants(id),click_id text unique not null,referrer text,utm_source text,utm_medium text,utm_campaign text,ip_hash text,user_agent text,created_at timestamptz not null default now());
create table leads(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns(id),participant_id uuid references campaign_participants(id),click_id text,name text,phone text not null,region text,status text not null default 'NEW',reject_reason text,created_at timestamptz not null default now(),reviewed_at timestamptz);
create index leads_campaign_phone_idx on leads(campaign_id,phone);
create table lead_status_history(id uuid primary key default gen_random_uuid(),lead_id uuid not null references leads(id),from_status text,to_status text not null,note text,actor_id uuid references users(id),created_at timestamptz not null default now());
create table posting_submissions(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns(id),user_id uuid not null references users(id),post_url text not null,status text not null default 'SUBMITTED',memo text,review_note text,submitted_at timestamptz not null default now(),reviewed_at timestamptz);
create unique index posting_unique_url_idx on posting_submissions(post_url);
create table earning_ledger(id uuid primary key default gen_random_uuid(),user_id uuid not null references users(id),campaign_id uuid references campaigns(id),source_type text not null,source_id uuid,amount integer not null,description text,created_at timestamptz not null default now());
create table withdrawal_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references users(id),amount integer not null,status text not null default 'REQUESTED',bank_name text,account_number_enc text,account_holder text,requested_at timestamptz not null default now(),processed_at timestamptz);
create table audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references users(id),action text not null,target_type text,target_id text,metadata jsonb,created_at timestamptz not null default now());